mapper.update:
UPDATE knowledge_info
SET item_count = (
    SELECT COUNT(*)
    FROM knowledge_item ki
    WHERE ki.kid = #{kid}
    AND ki.del_flag = '0'
)
WHERE kid = #{kid}

UPDATE knowledge_info
SET fragment_count = (
    SELECT COUNT(*)
    FROM knowledge_fragment kf
    WHERE kf.kid = #{kid}
    AND kf.del_flag = '0'
)
WHERE kid = #{kid}

UPDATE knowledge_info
SET data_size = #{dataSize}
WHERE kid = #{kid}
